def solve(s):
	len_s = len(s)
	cur = [False] * len_s
	let = 'z'
	if len_s - 1 > 0:
		for i in range(len_s - 1, 0, -1):
			if s[i] <= let:
				cur[i] = True
				let = s[i]
		if s[0] <= let:
			cur[0] = True
			let = s[0]
	before = ''
	after = ''
	got = []
	for i in range(0, len_s):
		if cur[i]:
			before += s[i]
			got.append(i)
		else:
			after += s[i]
	for i in range(len(before)):
		if len(after) > 0 and after[0] < before[i]:
			for j in range(i, len(got)):
				cur[got[j]] = False
	before = ''
	after = ''
	got = []
	for i in range(0, len_s):
		if cur[i]:
			before += s[i]
			got.append(i)
		else:
			after += s[i]
	count = 0
	for i in range(0, len(after)):
		if after[i] != after[0]:
			if after[i] > after[0]:
				break
			while len(before) > 0 and before[-1] == after[0]:
				cur[got[-1]] = False
				got.pop(-1)
				before = before[:-1]
	before = ''
	after = ''
	got = []
	for i in range(0, len_s):
		if cur[i]:
			before += s[i]
			got.append(i)
		else:
			after += s[i]
	res = before + after
	return res
